import { mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { pathToFileURL } from "node:url"

import { afterEach, describe, expect, it } from "vitest"

import {
  DEFAULT_DEV_PORTS,
  parseWorktreePorts,
  resolveDevPorts,
} from "./resolve-dev-ports.ts"

const WORKTREE_ENV = [
  "# Generated by scripts/worktree/worktree.sh — slot 3. Do not commit.",
  "WORKTREE_SLOT=3",
  "DEV_PORT=21030",
  "PREVIEW_PORT=21031",
  "",
].join("\n")

describe("parseWorktreePorts", () => {
  it("reads the slot's dev and preview ports", () => {
    expect(parseWorktreePorts(WORKTREE_ENV)).toEqual({
      dev: 21030,
      preview: 21031,
    })
  })

  it.each([
    ["a missing port", "DEV_PORT=21030\n"],
    ["a port out of range", "DEV_PORT=21030\nPREVIEW_PORT=70000\n"],
    ["a port that is not a number", "DEV_PORT=21030\nPREVIEW_PORT=abc\n"],
  ])("rejects %s, naming the fix", (_, text) => {
    expect(() => parseWorktreePorts(text)).toThrow(/pnpm worktree:setup/)
  })
})

describe("resolveDevPorts", () => {
  let directory: string | undefined

  afterEach(() => {
    if (directory) rmSync(directory, { recursive: true, force: true })
    directory = undefined
  })

  function envFile(contents?: string): URL {
    directory = mkdtempSync(join(tmpdir(), "dev-ports-"))
    const path = join(directory, ".env.worktree")
    if (contents !== undefined) writeFileSync(path, contents)
    return pathToFileURL(path)
  }

  it("keeps the default ports outside a parallel worktree", () => {
    expect(resolveDevPorts(envFile())).toBe(DEFAULT_DEV_PORTS)
  })

  it("uses the worktree's own ports from .env.worktree", () => {
    expect(resolveDevPorts(envFile(WORKTREE_ENV))).toEqual({
      dev: 21030,
      preview: 21031,
    })
  })
})
